                        "description": "会社名"
                    },
                },
                "required": []
            }
          }
    },
    {
        "type":"function",
        "function": {
            "name": "get_stock_price",
            "description": "特定の会社の株価情報を取得",
            "parameters": {
                "type": "object",
                "properties": {
                    "symbol": {
                        "type": "string",
                        "description": "株取引市場における会社のシンボル"
                    },
                },
                "required": ["symbol"]
            }
          }
    }
]
この時以下の発言に対してJSON形式で使用できる関数およびその引数を"name"及び"properties"にそれぞれ格納して出力してください。また複数関数を順番に実行する必要がある場合は順番がわかるようにまとめてJSONに格納してください。
### 発言
医療関係の会社の株価を比べて分析したい。

Answer:
[
  {
    "name": "search_company",
    "properties": {
      "keyword": "医療"
    }
  },
  {
    "name": "get_stock_symbol",
    "properties": {
      "company_name": "<search_companyで見つけた会社名>"
    }
  },
  {
    "name": "get_stock_price",
    "properties": {
      "symbol": "<get_stock_symbolで取得したシンボル>"
    }
  }
]

ModelAnswer:
以下のJSON形式で、関連する関数とその引数を指定します。医療関係の会社の株価を比較・分析するためには、まず会社名からシンボルを取得し、その後株価情報を取得する必要があります。

```json
{
  "functions": [
    {
      "name": "get_stock_symbol",
      "parameters": {
        "company_name": "医療関係の会社名（例: 'ジョンソン・エンド・ジョンソン'）"
      }
    },
    {
      "name": "get_stock_price",
      "parameters": {
        "symbol": "[上記で取得したシンボル]"
      }
    }
  ]
}
```

### 補足説明
1. **`get_stock_symbol`**: 医療関係の会社名（例: ジョンソン・エンド・ジョンソン）を入力し、対応する株取引市場のシンボル（例: JNJ）を取得します。
2. **`get_stock_price`**: 取得したシンボルを使用して、現在の株価情報（開値、終値、高値、安値など）を取得します。

### 複数関数の順番
- まず`get_stock_symbol`でシンボルを取得
- 次に`get_stock_price`で株価情報を取得

必要に応じて、複数の医療関連企業に対して同じ処理を行う場合は、各企業ごとに上記処理を繰り返します。
